/**
 * Playwright webServer entry generated by `withZitadel()`: boots an ephemeral
 * seeded Zitadel and writes the handshake file that the app runner and the
 * test fixtures read. Stays in the foreground; SIGTERM/SIGINT stop the
 * instance. Configuration arrives as JSON in ZITADEL_TESTING_SUPERVISOR.
 */
import { access, rm } from "node:fs/promises";

import { writeHandshake } from "./handshake";
import { startLocalZitadel } from "./index";
import { parseSupervisorConfig, requireHandshakePath, SUPERVISOR_CONFIG_ENV } from "./orchestration";
import type { LocalZitadel } from "./types";

const LOG = "[zitadel-testing]";

async function main(): Promise<void> {
  const config = parseSupervisorConfig(process.env[SUPERVISOR_CONFIG_ENV]);
  const handshakePath = requireHandshakePath(process.env);

  if (config.serverBinary) {
    // In-repo platform packages ship no binary; fail fast with the fix.
    await access(config.serverBinary).catch(() => {
      console.error(
        `${LOG} server binary not found at ${config.serverBinary}` +
          (config.serverBinaryHint ? ` — ${config.serverBinaryHint}` : ""),
      );
      process.exit(1);
    });
  }

  // Signal handlers close over this binding before the asynchronous boot
  // assigns it.
  // oxlint-disable-next-line prefer-const
  let zitadel: LocalZitadel | undefined;
  let signalled = false;
  let finishing: Promise<void> | undefined;

  const finish = (code: number): Promise<void> => {
    finishing ??= (async () => {
      let exitCode = code;
      try {
        await zitadel?.stop();
      } catch (error) {
        console.error(`${LOG} stop failed: ${(error as Error).message}`);
        exitCode = 1;
      }
      await rm(handshakePath, { force: true }).catch(() => undefined);
      process.exit(exitCode);
    })();
    return finishing;
  };

  // Handlers are installed before the boot so a cancellation arriving while
  // the instance comes up (or before the handshake is written) still tears it
  // down.
  const onSignal = (signal: NodeJS.Signals): void => {
    signalled = true;
    console.log(
      `${LOG} ${signal} received${zitadel ? ", stopping instance" : " during boot; stopping once ready"}`,
    );
    if (zitadel) {
      void finish(0);
    }
  };
  process.on("SIGTERM", onSignal);
  process.on("SIGINT", onSignal);

  await rm(handshakePath, { force: true });

  zitadel = await startLocalZitadel({
    port: config.port,
    appOrigins: config.appOrigins,
    serverBinary: config.serverBinary,
    dir: config.dir,
    keep: config.keep,
    projectName: config.projectName,
    preset: config.preset,
    useCase: config.useCase,
    timeoutMs: config.timeoutMs,
  });
  if (signalled) {
    await finish(0);
    return;
  }

  try {
    await writeHandshake(handshakePath, zitadel.handle);
  } catch (error) {
    console.error(`${LOG} failed to write handshake: ${(error as Error).message}`);
    await finish(1);
    return;
  }
  console.log(
    `${LOG} instance ready at ${zitadel.handle.baseUrl} (project ${zitadel.handle.projectId})`,
  );

  setInterval(() => {
    /* keep the event loop alive; Playwright owns this process's lifetime */
  }, 60_000);
}

main().catch((error: unknown) => {
  console.error(`${LOG} ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
});
